type LeaderboardVisualEntry = {
  id: string;
  name: string;
  value: number;
  valueLabel: string;
  metaLabel?: string;
};

function LeaderboardPanel({
  title,
  description,
  entries,
  color,
}: {
  title: string;
  description: string;
  entries: LeaderboardVisualEntry[];
  color: string;
}) {
  if (entries.length === 0) return null;
  const maxValue = Math.max(...entries.map(entry => Number(entry.value) || 0), 1);

  return (
    <ChartPanel title={title} description={description} height={Math.max(220, entries.length * 53 + 24)}>
      <div className="crm-leaderboard-list">
        {entries.map((entry, index) => {
          const width = entry.value > 0 ? Math.max(2, entry.value / maxValue * 100) : 0;
          const rankClass = index === 0 ? "is-first" : index === 1 ? "is-second" : index === 2 ? "is-third" : "";
          return (
            <div className="crm-leaderboard-row" key={entry.id}>
              <span className={`crm-leaderboard-rank ${rankClass}`}>{String(index + 1).padStart(2, "0")}</span>
              <div className="crm-leaderboard-main">
                <div className="crm-leaderboard-topline">
                  <span className="crm-leaderboard-name" title={entry.name}>{entry.name}</span>
                  <span className="crm-leaderboard-value">{entry.valueLabel}</span>
                </div>
                <div className="crm-leaderboard-track">
                  <span
                    className="crm-leaderboard-fill"
                    style={{ width: `${width}%`, "--bar-color": color } as React.CSSProperties}
                  />
                </div>
              </div>
              {entry.metaLabel && <span className="crm-leaderboard-meta">{entry.metaLabel}</span>}
            </div>
          );
        })}
      </div>
    </ChartPanel>
  );
}

function TargetGaugePanel({
  entries,
}: {
  entries: Array<{ id: string; name: string; target: number; closing: number }>;
}) {
  if (entries.length === 0) return null;

  return (
    <ChartPanel
      title="Pencapaian Closing terhadap Target HR"
      description="Setiap indikator menunjukkan closing aktual dibandingkan target KPI HR pada periode terpilih."
      height={Math.max(220, Math.ceil(entries.length / 4) * 142 + 24)}
    >
      <div className="crm-target-grid">
        {entries.map(entry => {
          const hasTarget = entry.target > 0;
          const percentage = hasTarget ? entry.closing / entry.target * 100 : 0;
          const ringValue = Math.min(Math.max(percentage, 0), 100);
          const ringColor = percentage >= 100 ? COLORS.green : percentage >= 70 ? COLORS.orange : "#3B82F6";
          return (
            <div className="crm-target-card" key={entry.id}>
              <div
                className="crm-target-ring"
                style={{ background: `conic-gradient(${ringColor} ${ringValue}%, #E8EEF5 0)` }}
              >
                <div className="crm-target-ring-inner">
                  <strong>{hasTarget ? `${percentage.toFixed(0)}%` : "—"}</strong>
                  <span>ACHIEVEMENT</span>
                </div>
              </div>
              <div className="crm-target-info">
                <strong title={entry.name}>{entry.name}</strong>
                <span>{entry.closing.toLocaleString("id-ID")} / {hasTarget ? entry.target.toLocaleString("id-ID") : "Target belum diatur"} closing</span>
              </div>
            </div>
          );
        })}
      </div>
    </ChartPanel>
  );
}

function formatCompactCurrency(value: number | string) {
  const amount = Number(value) || 0;
  const absolute = Math.abs(amount);
  if (absolute >= 1000000000) return "Rp " + (amount / 1000000000).toFixed(1) + " M";
  if (absolute >= 1000000) return "Rp " + (amount / 1000000).toFixed(1) + " jt";
  if (absolute >= 1000) return "Rp " + (amount / 1000).toFixed(0) + " rb";
  return formatCurrency(amount);
}


function ErrorOrLoading({ isLoading, isError, error, }: {
    isLoading: boolean;
    isError: boolean;
    error: unknown;
}) {
    if (isLoading) {
        return (<LoadingState label="Memuat laporan..."/>);
    }
    if (isError) {
        return (<ErrorState message={extractErrorMessage(error)}/>);
    }
    return null;
}

// Opsi CSV telah dihapus dari daftar format ekspor default
const EXPORT_FORMATS: { format: ReportExportFormat; label: string }[] = [
    { format: "xlsx", label: "Excel" }, 
    { format: "pdf", label: "PDF" },
];

function exportDateId(date: Date) { return date.toISOString().slice(0, 10); }
function exportDateText(date: Date) { return date.toLocaleString("id-ID", { dateStyle: "long", timeStyle: "short" }); }
function downloadBlob(blob: Blob, filename: string) {
    const url = URL.createObjectURL(blob), anchor = document.createElement("a");
    anchor.href = url; anchor.download = filename; document.body.appendChild(anchor); anchor.click(); anchor.remove();
    window.setTimeout(() => URL.revokeObjectURL(url), 1200);
}
function escapeCsvValue(value: unknown) {
    const text = value === null || value === undefined ? "" : String(value);
    return `"${text.replace(/"/g, '""')}"`;
}
function exportCrmCsv(filenameBase: string, rows: ExportRow[]) {
    const exportedAt = new Date(), headers = Object.keys(rows[0] ?? {}), delimiter = ";";
    const csvRows = [headers.map(escapeCsvValue).join(delimiter), ...rows.map(row => headers.map(header => escapeCsvValue(row[header])).join(delimiter))];
    const csv = `\uFEFF${csvRows.join("\r\n")}`;
    downloadBlob(new Blob([csv], { type: "text/csv;charset=utf-8" }), `msdc-crm-${filenameBase}-${exportDateId(exportedAt)}.csv`);
}
function isCurrencyHeader(header: string) { return /(nilai|revenue|mrr|arr|amount|pendapatan)/i.test(header); }
function formatPdfValue(header: string, value: unknown) {
    if (value === null || value === undefined || value === "") return "—";
    return typeof value === "number" && isCurrencyHeader(header) ? formatCurrency(value) : String(value);
}
function drawPdfHeader(doc: jsPDF, reportName: string, exportedAt: Date) {
    const W = doc.internal.pageSize.getWidth();
    drawMsdcPdfHeader(doc, { title: `Laporan CRM — ${reportName}`, docLabel: "Laporan CRM", marginX: 10 });

    doc.setTextColor(EXPORT_BRAND.slate); doc.setFont("helvetica", "normal"); doc.setFontSize(7.5);
    doc.text("MSDC Surabaya", 10, 43);
    doc.text(`Diekspor: ${exportDateText(exportedAt)}`, W - 10, 43, { align: "right" });
}
function exportCrmPdf(reportName: string, filenameBase: string, rows: ExportRow[]) {
    const exportedAt = new Date(), doc = new jsPDF({ orientation: "landscape", unit: "mm", format: "a4" });
    const W = doc.internal.pageSize.getWidth(), H = doc.internal.pageSize.getHeight(), headers = Object.keys(rows[0] ?? {});
    drawPdfHeader(doc, reportName, exportedAt); let y = 50;
    doc.setTextColor(EXPORT_BRAND.navyText); doc.setFont("helvetica", "bold"); doc.setFontSize(9); doc.text(`Data ${reportName}`, 10, y); y += 4;
    autoTable(doc, {
        startY: y, head: [headers], body: rows.map(row => headers.map(header => formatPdfValue(header, row[header]))), theme: "grid",
        margin: { top: 49, left: 10, right: 10, bottom: 12 }, styles: { font: "helvetica", fontSize: 7, cellPadding: 2, textColor: EXPORT_BRAND.navyText, lineColor: EXPORT_BRAND.border, lineWidth: 0.2, overflow: "linebreak" },
        headStyles: { fillColor: EXPORT_BRAND.navy, textColor: "#FFFFFF", fontStyle: "bold" }, alternateRowStyles: { fillColor: EXPORT_BRAND.light },
        didDrawPage: () => drawPdfHeader(doc, reportName, exportedAt),
    });
    const pages = doc.getNumberOfPages();
    for (let page = 1; page <= pages; page += 1) { doc.setPage(page); doc.setTextColor(EXPORT_BRAND.slate); doc.setFont("helvetica", "normal"); doc.setFontSize(7); doc.text(`Halaman ${page} / ${pages}`, W - 10, H - 5, { align: "right" }); }
    doc.save(`msdc-crm-${filenameBase}-${exportDateId(exportedAt)}.pdf`);
}
function buildColumnSpans(itemCount: number, totalColumns = 8) {
    return Array.from({ length: itemCount }, (_, index) => {
        const start = Math.floor(index * totalColumns / itemCount) + 1;
        const end = Math.max(start, Math.floor((index + 1) * totalColumns / itemCount));
        return [start, end] as const;
    });
}
async function exportCrmExcel(reportName: string, filenameBase: string, rows: ExportRow[]) {
    const exportedAt = new Date(), headers = Object.keys(rows[0] ?? {}), cols = Math.max(8, headers.length);
    const workbook = new ExcelJS.Workbook();
workbook.creator = "MSDC Surabaya";
workbook.created = exportedAt;
    const ws = workbook.addWorksheet(reportName.slice(0, 31), { views: [{ showGridLines: false }], pageSetup: { orientation: "landscape", paperSize: 9, fitToPage: true, fitToWidth: 1, fitToHeight: 0 } });

    // Header Excel diselaraskan dengan CrmDashboardPage: logo kiri,
    // judul/subjudul di tengah, identitas CRM-Sales kanan, aksen kuning.
    // Jumlah kolom tetap dinamis agar struktur tabel laporan tidak berubah.
    for (let c = 1; c <= cols; c += 1) ws.getColumn(c).width = 16;
    for (let r = 1; r <= 4; r += 1) {
        ws.getRow(r).height = r === 2 ? 25 : 22;
        for (let c = 1; c <= cols; c += 1) {
            ws.getCell(r, c).fill = { type: "pattern", pattern: "solid", fgColor: { argb: "FF092747" } };
        }
    }

    const msdcImage = workbook.addImage({ base64: MSDC_EXPORT_LOGO, extension: "png" });
    ws.addImage(msdcImage, { tl: { col: 0.38, row: 0.35 }, ext: { width: 158, height: 62 } });

    const titleEnd = cols - 2;
    const rightStart = cols - 1;
    ws.mergeCells(2, 3, 2, titleEnd);
    ws.getCell(2, 3).value = `Laporan CRM — ${reportName}`;
    ws.getCell(2, 3).font = { name: "Aptos Display", size: 17, bold: true, color: { argb: "FFFFFFFF" } };
    ws.getCell(2, 3).alignment = { horizontal: "center", vertical: "middle", shrinkToFit: true };

    ws.mergeCells(3, 3, 3, titleEnd);
    ws.getCell(3, 3).value = "Kelola pelanggan, peluang, dan kontrak layanan Data Center";
    ws.getCell(3, 3).font = { name: "Aptos", size: 9, color: { argb: "FFCBD5E1" } };
    ws.getCell(3, 3).alignment = { horizontal: "center", vertical: "middle", shrinkToFit: true };

    ws.mergeCells(2, rightStart, 2, cols);
    ws.getCell(2, rightStart).value = "CRM & SALES";
    ws.getCell(2, rightStart).font = { name: "Aptos", size: 9, bold: true, color: { argb: "FFFFFFFF" } };
    ws.getCell(2, rightStart).alignment = { horizontal: "right", vertical: "middle", indent: 2 };

    ws.mergeCells(3, rightStart, 3, cols);
    ws.getCell(3, rightStart).value = "MSDC Surabaya";
    ws.getCell(3, rightStart).font = { name: "Aptos", size: 8, color: { argb: "FFCBD5E1" } };
    ws.getCell(3, rightStart).alignment = { horizontal: "right", vertical: "middle", indent: 2 };

    ws.mergeCells(4, rightStart, 4, cols);
    ws.getCell(4, rightStart).value = "Dokumen Laporan";
    ws.getCell(4, rightStart).font = { name: "Aptos", size: 8, color: { argb: "FFCBD5E1" } };
    ws.getCell(4, rightStart).alignment = { horizontal: "right", vertical: "middle", indent: 2 };

    for (let c = 1; c <= cols; c += 1) {
        ws.getCell(5, c).fill = { type: "pattern", pattern: "solid", fgColor: { argb: "FFF7AB00" } };
    }
    ws.getRow(5).height = 5;
    const split = Math.floor(cols / 2);
    ws.mergeCells(6, 1, 6, split);
    ws.getCell(6, 1).value = "MSDC Surabaya | CRM & Sales";
    ws.getCell(6, 1).font = { size: 9, bold: true, color: { argb: "FF64748B" } };
    ws.getCell(6, 1).alignment = { vertical: "middle" };
    ws.mergeCells(6, split + 1, 6, cols);
    ws.getCell(6, split + 1).value = `Diekspor: ${exportDateText(exportedAt)}`;
    ws.getCell(6, split + 1).font = { size: 9, color: { argb: "FF64748B" } };
    ws.getCell(6, split + 1).alignment = { horizontal: "right", vertical: "middle" };
    let row = 8;
    ws.mergeCells(row, 1, row, cols); ws.getCell(row, 1).value = `Data ${reportName}`; ws.getCell(row, 1).font = { size: 11, bold: true, color: { argb: "FF16213D" } }; row += 1;
    const tableHeaderRow = row, spans = buildColumnSpans(headers.length, cols);
    headers.forEach((header, index) => {
        const [start, end] = spans[index]; if (start !== end) ws.mergeCells(row, start, row, end);
        for (let c = start; c <= end; c += 1) ws.getCell(row, c).fill = { type: "pattern", pattern: "solid", fgColor: { argb: "FF092747" } };
        const cell = ws.getCell(row, start); cell.value = header; cell.font = { bold: true, color: { argb: "FFFFFFFF" }, size: 9 }; cell.alignment = { vertical: "middle", wrapText: true };
    });
    ws.getRow(row).height = 24; row += 1;
    rows.forEach((item, rowIndex) => {
        headers.forEach((header, index) => {
            const [start, end] = spans[index]; if (start !== end) ws.mergeCells(row, start, row, end);
            const value = item[header], cell = ws.getCell(row, start); cell.value = value === null || value === undefined || value === "" ? "—" : (value as string | number | boolean | Date);
            cell.font = { size: 9, color: { argb: "FF16213D" }, bold: index === 0 }; cell.alignment = { vertical: "top", wrapText: true };
            if (typeof value === "number" && isCurrencyHeader(header)) cell.numFmt = '"Rp" #,##0';
            for (let c = start; c <= end; c += 1) { ws.getCell(row, c).fill = { type: "pattern", pattern: "solid", fgColor: { argb: rowIndex % 2 ? "FFF8FAFC" : "FFFFFFFF" } }; ws.getCell(row, c).border = { bottom: { style: "hair", color: { argb: "FFE5E7EB" } } }; }
        }); row += 1;
    });
    ws.views = [{ state: "frozen", ySplit: 6, showGridLines: false }]; ws.headerFooter.oddFooter = `&LMSDC Surabaya&C${reportName}&RPage &P / &N`; ws.pageSetup.printTitlesRow = `${tableHeaderRow}:${tableHeaderRow}`;
    const buffer = await workbook.xlsx.writeBuffer();
    downloadBlob(new Blob([buffer as unknown as BlobPart], { type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" }), `msdc-crm-${filenameBase}-${exportDateId(exportedAt)}.xlsx`);
}

function ExportButtons({
    reportName,
    filenameBase,
    rows,
    formats = EXPORT_FORMATS,
}: {
    reportName: string;
    filenameBase: string;
    rows: ExportRow[];
    formats?: { format: ReportExportFormat; label: string }[];
}) {
    const [localExporting, setLocalExporting] = useState<ReportExportFormat | null>(null), [localError, setLocalError] = useState<string | null>(null);
    if (!rows.length) return null; const pending = localExporting !== null;
    async function handleExport(format: ReportExportFormat) {
        setLocalError(null); setLocalExporting(format);
        try {
            if (format === "csv") exportCrmCsv(filenameBase, rows);
            else if (format === "pdf") exportCrmPdf(reportName, filenameBase, rows);
            else await exportCrmExcel(reportName, filenameBase, rows);
        } catch (error) { setLocalError(error instanceof Error ? error.message : "Gagal membuat file export."); }
        finally { setLocalExporting(null); }
    }
    return (<div className="crm-report-export-row">
      <Download size={15} color={COLORS.slate}/><span className="crm-report-export-label">Export:</span>
      {formats.map(item => (<button className="crm-report-export-button" key={item.format} type="button" disabled={pending} onClick={() => void handleExport(item.format)}>{localExporting === item.format ? "Membuat..." : item.label}</button>))}
      {localError && <span style={{ color: COLORS.red, fontSize: "0.7rem" }}>{localError}</span>}
    </div>);
}

/* ============================================================
   PIPELINE FUNNEL
============================================================ */
function PipelineFunnelReport() {
  const { data: leads, isLoading: l1 } = useLeadList({ per_page: 1 });
  const { data: opps, isLoading: l2 } = useOpportunityList({ per_page: 1 });
  const { data: quotations, isLoading: l3 } = useQuotationList({ per_page: 1 });
  const { data: salesOrders, isLoading: l4 } = useSalesOrderList({ per_page: 1 });
  const { data: contracts, isLoading: l5 } = useContractList({ per_page: 1 });
  const loading = l1 || l2 || l3 || l4 || l5;

  if (loading) {
    return <div style={{ paddingTop: "1rem" }}><LoadingState label="Memuat funnel..." /></div>;
  }

  const stages = [
    { label: "Lead", value: leads?.total ?? 0, color: "#3B82F6" },
    { label: "Opportunity", value: opps?.total ?? 0, color: COLORS.navy },
    { label: "Quotation", value: quotations?.total ?? 0, color: COLORS.orangeDark },
    { label: "Sales Order", value: salesOrders?.total ?? 0, color: COLORS.orange },
    { label: "Contract", value: contracts?.total ?? 0, color: COLORS.green },
  ];
  const rows: ExportRow[] = stages.map(stage => ({ Tahap: stage.label, Jumlah: stage.value }));

  return (
    <div style={{ paddingTop: "1rem", display: "flex", flexDirection: "column", gap: "1rem", minWidth: 0, width: "100%" }}>
      <ChartPanel
        title="Alur Konversi Pipeline CRM"
        description="Perbandingan jumlah pada setiap tahap pipeline. Arahkan kursor ke batang untuk melihat rincian."
        height={320}
      >
        <ResponsiveContainer width="100%" height="100%">
          <BarChart data={stages} layout="vertical" margin={{ top: 10, right: 30, bottom: 5, left: 8 }}>
            <CartesianGrid stroke="#EAF0F6" strokeDasharray="3 4" horizontal={false} />
            <XAxis type="number" allowDecimals={false} tick={CHART_AXIS_TICK} axisLine={{ stroke: "#E2E8F0" }} tickLine={false} />
            <YAxis dataKey="label" type="category" width={95} tick={CHART_AXIS_TICK} axisLine={false} tickLine={false} />
            <Tooltip
              cursor={{ fill: "rgba(241, 245, 249, 0.6)" }}
              contentStyle={CHART_TOOLTIP_STYLE}
              labelStyle={{ color: "#E2E8F0", fontWeight: 700 }}
              itemStyle={{ color: "#FFFFFF" }}
              formatter={(value) => [`${Number(value ?? 0).toLocaleString("id-ID")} data`, "Jumlah"]}
            />
            <ChartBar dataKey="value" name="Jumlah" radius={[0, 8, 8, 0]} maxBarSize={30} isAnimationActive animationDuration={1100} animationEasing="ease-out">
              {stages.map(stage => <Cell key={stage.label} fill={stage.color} />)}
            </ChartBar>
          </BarChart>
        </ResponsiveContainer>
      </ChartPanel>
      <div className="crm-pipeline-conversions" aria-label="Rasio konversi antar tahap">
        {stages.slice(1).map((stage, index) => {
          const previous = stages[index];
          const conversion = previous.value > 0 ? Math.round(stage.value / previous.value * 100) : null;
          return (
            <div className="crm-pipeline-conversion" key={stage.label}>
              <span>{previous.label} → {stage.label}</span>
              <strong>{conversion === null ? "—" : `${conversion}%`}</strong>
            </div>
          );
        })}
      </div>
      <ExportButtons reportName="Pipeline Funnel" filenameBase="pipeline-funnel" rows={rows} />
    </div>
  );
}


