function CompanyProgressView() {
  const [search, setSearch] = useState("");

  const leadsQ = useLeadList({ page: 1, per_page: 100 });
  const oppsQ = useOpportunityList({ page: 1, per_page: 100 });
  const quotesQ = useQuotationList({ page: 1, per_page: 100 });
  const contractsQ = useContractList({ page: 1, per_page: 100 });
  const ordersQ = useSalesOrderList({ page: 1, per_page: 100 });
  const customersQ = useCustomerList({ page: 1, per_page: 100 });

  const queries = [
    leadsQ, oppsQ, quotesQ,
    contractsQ, ordersQ, customersQ
  ];

  const loading = queries.some(q => q.isLoading);
  const failed = queries.some(q => q.isError);
  const partial = queries.some(
    q => (q.data?.last_page ?? 1) > 1
  );

  const leads = leadsQ.data?.data ?? [];
  const opps = oppsQ.data?.data ?? [];
  const quotes = quotesQ.data?.data ?? [];
  const contracts = contractsQ.data?.data ?? [];
  const orders = ordersQ.data?.data ?? [];
  const customers = customersQ.data?.data ?? [];

  type Row = {
    key: string;
    company: string;
    pic: string;
    stage: string;
    status: string;
    updated: string;
    link: string;
    updatedTimestamp: number | null;
  };

  const rows: Row[] = [];

  function latest<T extends { updated_at: string }>(
    items: T[]
  ): T | undefined {
    return [...items].sort(
      (a, b) =>
        Date.parse(b.updated_at) -
        Date.parse(a.updated_at)
    )[0];
  }

  function addCompany(
    key: string,
    company: string,
    customerId: number | null,
    leadId?: number
  ) {
    const relatedLeads = leads.filter(l =>
      (customerId !== null &&
        l.converted_customer_id === customerId) ||
      (leadId !== undefined && l.id === leadId)
    );

    const leadIds = new Set(
      relatedLeads.map(l => l.id)
    );

    const relatedOpps = opps.filter(o =>
      (customerId !== null &&
        o.customer_id === customerId) ||
      (o.lead_id !== null && leadIds.has(o.lead_id))
    );

    const oppIds = new Set(
      relatedOpps.map(o => o.id)
    );

    const relatedQuotes = quotes.filter(q =>
      (customerId !== null &&
        q.customer_id === customerId) ||
      (q.lead_id !== null && leadIds.has(q.lead_id)) ||
      (q.opportunity_id !== null &&
        oppIds.has(q.opportunity_id))
    );

    const quoteIds = new Set(
      relatedQuotes.map(q => q.id)
    );

    const relatedContracts = contracts.filter(c =>
      (customerId !== null &&
        c.customer_id === customerId) ||
      (c.quotation_id !== null &&
        quoteIds.has(c.quotation_id))
    );

    const contractIds = new Set(
      relatedContracts.map(c => c.id)
    );

    const relatedOrders = orders.filter(o =>
      (customerId !== null &&
        o.customer_id === customerId) ||
      (o.contract_id !== null &&
        contractIds.has(o.contract_id)) ||
      (o.quotation_id !== null &&
        quoteIds.has(o.quotation_id))
    );

    const lead = latest(relatedLeads);
    const opp = latest(relatedOpps);
    const quote = latest(relatedQuotes);
    const contract = latest(relatedContracts);
    const order = latest(relatedOrders);

    if (!lead && !opp && !quote && !contract && !order) {
      return;
    }

    const current = order
      ? {
          stage: "Sales Order",
          status: order.status,
          link: `/crm-sales/sales-orders/${order.id}`
        }
      : contract
      ? {
          stage: "Contract",
          status: contract.status,
          link: `/crm-sales/contracts/${contract.id}`
        }
      : quote
      ? {
          stage: "Quotation",
          status: quote.status,
          link: `/crm-sales/quotations/${quote.id}`
        }
      : opp
      ? {
          stage: "Opportunity",
          status: opp.stage,
          link: "/crm-sales/opportunities"
        }
      : {
          stage: "Lead",
          status: lead!.status,
          link: "/crm-sales/leads"
        };

    const dates = [
      lead, opp, quote, contract, order
    ]
      .filter(
        (item): item is NonNullable<typeof item> =>
          !!item
      )
      .map(item => Date.parse(item.updated_at))
      .filter(Number.isFinite);

    const updatedTimestamp = dates.length
  ? Math.max(...dates)
  : null;

const updated = updatedTimestamp !== null
  ? new Date(updatedTimestamp).toLocaleDateString("id-ID")
  : "—";

    rows.push({ updatedTimestamp,
      key,
      company,
      pic:
        opp?.resolved_sales_employee?.full_name ||
        opp?.assigned_user?.name ||
        lead?.pic ||
        "Belum ditentukan",
      stage: current.stage,
      status: current.status.replace(/_/g, " "),
      updated,
      link: current.link
    });
  }

  customers.forEach(c =>
    addCompany(
      `customer-${c.id}`,
      c.company_name,
      c.id
    )
  );

  leads
    .filter(l =>
      !l.converted_customer_id ||
      !customers.some(
        c => c.id === l.converted_customer_id
      )
    )
    .forEach(l =>
      addCompany(
        `lead-${l.id}`,
        l.company_name,
        null,
        l.id
      )
    );

  const visible = rows.filter(r =>
    `${r.company} ${r.pic} ${r.stage}`
      .toLowerCase()
      .includes(search.toLowerCase())
  );

  
  return (
    <section
      style={{
        background: COLORS.white,
        border: `1px solid ${COLORS.border}`,
        borderRadius: 10,
        padding: "1rem 1.2rem",
        width: "100%",
        minWidth: 0,
        boxSizing: "border-box",
        marginBottom: 0,
      }}
    >
      <h2 style={{
        margin: "0 0 8px",
        color: COLORS.navy
      }}>
        Progres Perusahaan
      </h2>

      <p style={{
        fontSize: 13,
        color: COLORS.slate
      }}>
        Tahap terjauh yang tercatat dari Lead
        sampai Sales Order.
      </p>

      <input
        className="input"
        placeholder="Cari perusahaan atau PIC"
        value={search}
        onChange={e => setSearch(e.target.value)}
        style={{
          margin: "12px 0",
          maxWidth: 320
        }}
      />

      {loading ? (
        <p>Memuat data perusahaan...</p>
      ) : failed ? (
        <p role="alert">
          Sebagian data CRM gagal dimuat.
          Periksa koneksi dan akses API.
        </p>
      ) : (
        <>
          {partial && (
            <p style={{
              color: COLORS.orangeDark,
              fontSize: 12
            }}>
              Data belum lengkap: sementara hanya
              100 data pertama per modul.
            </p>
          )}

          <div style={{ overflowX: "auto" }}>
            <table style={{
              width: "100%",
              minWidth: 720,
              borderCollapse: "collapse"
            }}>
              <thead>
                <tr>
                  {[
                    "Perusahaan",
                    "PIC",
                    "Tahap terjauh",
                    "Status",
                    "Terakhir diperbarui",
                    "Tindak lanjut"
                  ].map(t => (
                    <th key={t} style={monitorHead}>
                      {t}
                    </th>
                  ))}
                </tr>
              </thead>

              <tbody>
                {visible.map(r => (
                  <tr key={r.key}>
                    <td style={monitorCell}>
                      {r.company}
                    </td>

                    <td style={monitorCell}>
                      {r.pic}
                    </td>

                    <td style={monitorCell}>
                      <Link to={r.link}>
                        {r.stage}
                      </Link>
                    </td>

                    <td style={monitorCell}>
                      {r.status}
                    </td>

                    <td style={monitorCell}>
                      {r.updated}
                    </td>
                    <td style={monitorCell}>
  {r.stage === "Sales Order" &&
   r.status.toLowerCase() === "active"
    ? "Sudah Sales Order"
    : r.pic === "Belum ditentukan"
    ? "Tetapkan PIC"
    : r.updatedTimestamp === null
    ? "Tanggal tidak tersedia"
    : Date.now() - r.updatedTimestamp >=
      7 * 24 * 60 * 60 * 1000
    ? "Perlu follow-up"
    : "Terpantau"}
</td>

                  </tr>
                ))}

                {visible.length === 0 && (
                  <tr>
                    <td colSpan={5} style={monitorCell}>
                      Tidak ada perusahaan yang cocok.
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </>
      )}
      
    </section>
  );
}

function MonitoringSalesReportView({ filters }: { filters: CrmReportFilters }) {
  const now = new Date();
  const [period, setPeriod] = useState<"monthly" | "yearly">("monthly");
  const [year, setYear] = useState(now.getFullYear());
  const [month, setMonth] = useState(now.getMonth() + 1);

  const periodFilters: CrmReportFilters = useMemo(() => {
    const dateFrom = period === "monthly"
      ? String(year) + "-" + String(month).padStart(2, "0") + "-01"
      : String(year) + "-01-01";
    const dateTo = period === "monthly"
      ? String(year) + "-" + String(month).padStart(2, "0") + "-" + String(new Date(year, month, 0).getDate()).padStart(2, "0")
      : String(year) + "-12-31";
    return { ...filters, include_all_pic: 1, date_from: dateFrom, date_to: dateTo };
  }, [filters, period, year, month]);

  const { data, isLoading, isError, error } = useSalesPerformanceReport(true, periodFilters);
  const employees = (data?.leaderboard ?? []) as MonitoringSalesRow[];
  const targeted = employees.filter(employee => employee.target_source === "hr_position" && employee.target_won_count != null);
  const totalClosing = employees.reduce((sum, employee) => sum + Number(employee.opportunities_won || 0), 0);
  const totalRevenue = employees.reduce((sum, employee) => sum + Number(employee.revenue_won || 0), 0);
  const totalTarget = targeted.reduce((sum, employee) => sum + Number(employee.target_won_count ?? 0), 0);
  const attributableClosing = targeted.reduce((sum, employee) => sum + Number(employee.opportunities_won || 0), 0);
  const achievement = totalTarget > 0 ? (attributableClosing / totalTarget * 100).toFixed(1) + "%" : "—";
  const customerFilterActive = filters.customer_id != null && filters.customer_id !== 0;

  const activityChartRows = [...employees]
    .sort((a, b) => (Number(b.leads_count) + Number(b.opportunities_count) + Number(b.quotations_count)) - (Number(a.leads_count) + Number(a.opportunities_count) + Number(a.quotations_count)))
    .slice(0, 8)
    .map(employee => ({
      name: employee.name,
      leads: Number(employee.leads_count) || 0,
      opportunities: Number(employee.opportunities_count) || 0,
      quotations: Number(employee.quotations_count) || 0,
      closing: Number(employee.opportunities_won) || 0,
    }));
  const revenueChartRows = [...employees]
    .sort((a, b) => Number(b.revenue_won || 0) - Number(a.revenue_won || 0))
    .slice(0, 8)
    .map(employee => ({ name: employee.name, revenue: Number(employee.revenue_won) || 0 }));
  const targetChartRows = targeted
    .map(employee => ({
      name: employee.name,
      target: Number(employee.target_won_count) || 0,
      closing: Number(employee.opportunities_won) || 0,
    }))
    .sort((a, b) => b.target - a.target)
    .slice(0, 8);

  return (
    <div style={{ paddingTop: "1rem", display: "flex", flexDirection: "column", gap: "1rem", minWidth: 0 }}>
      <div style={{ display: "flex", gap: "0.75rem", flexWrap: "wrap", alignItems: "end" }}>
        <label style={{ fontSize: "0.75rem", color: COLORS.navy, fontWeight: 700 }}>
          Periode
          <select className="input" value={period} onChange={e => setPeriod(e.target.value as "monthly" | "yearly")} style={{ display: "block", marginTop: 6, minWidth: 145 }}>
            <option value="monthly">Bulanan</option>
            <option value="yearly">Tahunan</option>
          </select>
        </label>
        {period === "monthly" && (
          <label style={{ fontSize: "0.75rem", color: COLORS.navy, fontWeight: 700 }}>
            Bulan
            <select className="input" value={month} onChange={e => setMonth(Number(e.target.value))} style={{ display: "block", marginTop: 6, minWidth: 145 }}>
              {Array.from({ length: 12 }, (_, index) => (
                <option key={index + 1} value={index + 1}>{new Date(2024, index, 1).toLocaleString("id-ID", { month: "long" })}</option>
              ))}
            </select>
          </label>
        )}
        <label style={{ fontSize: "0.75rem", color: COLORS.navy, fontWeight: 700 }}>
          Tahun
          <input className="input" type="number" min={2000} max={2100} value={year}
            onChange={e => { const value = Number(e.target.value); if (value >= 2000 && value <= 2100) setYear(value); }}
            style={{ display: "block", marginTop: 6, width: 115 }} />
        </label>
      </div>

      {isLoading || isError ? (
        <ErrorOrLoading isLoading={isLoading} isError={isError} error={error} />
      ) : (
        <>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(170px, 1fr))", gap: "0.75rem" }}>
            <StatBox label="Total Closing PIC" value={totalClosing} color={COLORS.green} />
            <StatBox label="Revenue Won PIC" value={formatCurrency(totalRevenue)} color={COLORS.green} />
            <StatBox label="Target Closing HR" value={targeted.length ? totalTarget : "Belum diatur"} />
            <StatBox label="Pencapaian Target HR" value={achievement} color={COLORS.green} />
          </div>

          {employees.length > 0 && (
            <div className="crm-report-chart-grid">
              <ChartPanel
                title="Aktivitas CRM per PIC"
                description="Komposisi Lead, Opportunity, Quotation, dan Closing pada 8 PIC dengan aktivitas terbanyak."
                height={Math.max(250, activityChartRows.length * 53 + 55)}
              >
                <div className="crm-activity-list">
                  {activityChartRows.map(row => {
                    const total = row.leads + row.opportunities + row.quotations;
                    const safeTotal = total || 1;
                    return (
                      <div className="crm-activity-row" key={row.name}>
                        <div className="crm-activity-header">
                          <strong title={row.name}>{row.name}</strong>
                          <span className="crm-activity-total">{total.toLocaleString("id-ID")} aktivitas · {row.closing} closing</span>
                        </div>
                        <div className="crm-activity-track">
                          <span className="crm-activity-segment" title={`Lead: ${row.leads}`} style={{ width: `${row.leads / safeTotal * 100}%`, background: "#3B82F6" }} />
                          <span className="crm-activity-segment" title={`Opportunity: ${row.opportunities}`} style={{ width: `${row.opportunities / safeTotal * 100}%`, background: COLORS.orange }} />
                          <span className="crm-activity-segment" title={`Quotation: ${row.quotations}`} style={{ width: `${row.quotations / safeTotal * 100}%`, background: "#8B5CF6" }} />
                        </div>
                        <div className="crm-activity-legend">
                          <span className="crm-activity-legend-item"><i className="crm-activity-legend-dot" style={{ background: "#3B82F6" }} />Lead {row.leads}</span>
                          <span className="crm-activity-legend-item"><i className="crm-activity-legend-dot" style={{ background: COLORS.orange }} />Opportunity {row.opportunities}</span>
                          <span className="crm-activity-legend-item"><i className="crm-activity-legend-dot" style={{ background: "#8B5CF6" }} />Quotation {row.quotations}</span>
                          <span className="crm-activity-legend-item"><i className="crm-activity-legend-dot" style={{ background: COLORS.green }} />Closing {row.closing}</span>
                        </div>
                      </div>
                    );
                  })}
                </div>
              </ChartPanel>

              <LeaderboardPanel
                title="Leaderboard Revenue Won per PIC"
                description="Peringkat 8 PIC berdasarkan nilai revenue Closed Won pada periode terpilih."
                entries={revenueChartRows.map((row, index) => ({
                  id: `${row.name}-${index}`,
                  name: row.name,
                  value: row.revenue,
                  valueLabel: formatCompactCurrency(row.revenue),
                  metaLabel: "Revenue Won",
                }))}
                color={COLORS.green}
              />

              <TargetGaugePanel
                entries={targetChartRows.map((row, index) => ({
                  id: `${row.name}-${index}`,
                  name: row.name,
                  target: row.target,
                  closing: row.closing,
                }))}
              />
            </div>
          )}

          <div className="crm-report-note">
            <p style={{ margin: 0, fontSize: "0.73rem", lineHeight: 1.65, color: COLORS.slate }}>
              Monitoring mencakup <strong>semua PIC di dropdown Lead</strong>, termasuk Sales, Marketing,
              Manager, jabatan lainnya, serta akun User yang tidak terhubung ke Employee HR.
              Setiap KPI dihitung dari transaksi CRM yang memiliki PIC/owner tersebut, bukan dari jabatannya.
              Closing dan revenue berasal dari Opportunity CLOSED WON. Target hanya muncul jika jabatan Employee HR
              memiliki KPI <strong>crm_opportunities_won</strong>; target tahunan adalah target bulanan x 12.
              Lead dibuat dan Opportunity dibuat mengikuti tanggal pembuatan, konversi mengikuti tanggal konversi,
              dan Won/Lost mengikuti tanggal closing. Quotation diterima menggunakan waktu update terakhir
              untuk status Accepted karena belum tersedia kolom accepted_at.
            </p>
            <Link to="/hr/positions" style={{ display: "inline-block", marginTop: "0.5rem", color: COLORS.orangeDark, fontSize: "0.73rem", fontWeight: 700, textDecoration: "none" }}>
              Kelola KPI di HR Position/Jabatan →
            </Link>
          </div>

          {employees.length > 0 && (
            <p style={{ margin: 0, color: COLORS.slate, fontSize: "0.72rem" }}>
              <strong>{employees.length}</strong> PIC terdaftar (seluruh jabatan). Target HR tersedia untuk <strong>{targeted.length}</strong> PIC.
            </p>
          )}

          {customerFilterActive && (
            <p style={{ margin: 0, color: COLORS.orangeDark, fontSize: "0.72rem" }}>
              Filter Customer aktif. Target HR hanya bisa dibandingkan untuk seluruh customer; pilih "Semua Customer".
            </p>
          )}

          {employees.length === 0 ? (
            <p style={{ margin: 0, color: COLORS.slate, fontSize: "0.75rem" }}>
              Belum ada PIC yang tersedia untuk dimonitor pada organisasi ini.
            </p>
          ) : (
            <div style={{ width: "100%", minWidth: 0, maxWidth: "100%", overflowX: "auto", border: "1px solid " + COLORS.border, borderRadius: 12 }}>
              <table className="crm-report-monitor-table" style={{ borderCollapse: "separate", borderSpacing: 0 }}>
                <thead><tr style={{ background: COLORS.soft }}>
                  <th style={{ ...monitorHead, minWidth: 180 }}>PIC (User / Employee HR)</th>
                  <th style={{ ...monitorHead, minWidth: 145 }}>Posisi / Jabatan</th>
                  <th style={{ ...monitorHead, textAlign: "right", minWidth: 95 }}>Lead Dibuat</th>
                  <th style={{ ...monitorHead, textAlign: "right", minWidth: 135 }}>Lead Dikonversi jadi Customer</th>
                  <th style={{ ...monitorHead, textAlign: "right", minWidth: 110 }}>Opportunity Dibuat</th>
                  <th style={{ ...monitorHead, textAlign: "right", minWidth: 125 }}>Opportunity Won (Closed Won)</th>
                  <th style={{ ...monitorHead, textAlign: "right", minWidth: 120 }}>Opportunity Lost</th>
                  <th style={{ ...monitorHead, textAlign: "right", minWidth: 112 }}>Quotation Dibuat</th>
                  <th style={{ ...monitorHead, textAlign: "right", minWidth: 130 }}>Quotation Diterima Customer</th>
                  <th style={{ ...monitorHead, textAlign: "right", minWidth: 95 }}>Closing</th>
                  <th style={{ ...monitorHead, textAlign: "right", minWidth: 100 }}>Target HR</th>
                  <th style={{ ...monitorHead, textAlign: "right", minWidth: 150 }}>Revenue Won</th>
                  <th style={{ ...monitorHead, textAlign: "right", minWidth: 110 }}>Pencapaian</th>
                </tr></thead>
                <tbody>
                  {employees.map(employee => {
                    const target = employee.target_source === "hr_position" ? employee.target_won_count : null;
                    const percentage = target != null && Number(target) > 0
                      ? (Number(employee.opportunities_won || 0) / Number(target) * 100).toFixed(1) + "%"
                      : "—";
                    const numericCell: React.CSSProperties = { ...monitorCell, textAlign: "right", fontVariantNumeric: "tabular-nums" };
                    return (
                      <tr key={employee.choice_id}>
                        <td style={monitorCell}>
                          <strong style={{ display: "block" }}>{employee.name}</strong>
                          {employee.user_id == null && <span style={{ color: COLORS.slate, fontSize: "0.68rem" }}>Employee HR tanpa akun User</span>}
                          {employee.employee_id == null && <span style={{ color: COLORS.slate, fontSize: "0.68rem" }}>Akun User (belum terhubung Employee HR)</span>}
                        </td>
                        <td style={monitorCell}>{employee.position_title || "—"}</td>
                        <td style={numericCell}>{employee.leads_count}</td>
                        <td style={numericCell}>{employee.leads_converted_count}</td>
                        <td style={numericCell}>{employee.opportunities_count}</td>
                        <td style={numericCell}>{employee.opportunities_won}</td>
                        <td style={numericCell}>{employee.opportunities_lost}</td>
                        <td style={numericCell}>{employee.quotations_count}</td>
                        <td style={numericCell}>{employee.quotations_accepted_count}</td>
                        <td style={numericCell}>{employee.opportunities_won}</td>
                        <td style={numericCell}>{target ?? <span style={{ color: COLORS.slate }}>Belum diatur</span>}</td>
                        <td style={numericCell}>{formatCurrency(Number(employee.revenue_won || 0))}</td>
                        <td style={{ ...numericCell, fontWeight: 700, color: percentage !== "—" ? COLORS.green : COLORS.slate }}>{percentage}</td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          )}
        </>
      )}
    </div>
  );
}


/* ============================================================
   QUOTATION SUMMARY
============================================================ */
const QT_STATUS_LABELS: Record<string, string> = {
    draft: "Draft",
    waiting_approval: "Menunggu Approval",
    approved: "Disetujui",
    sent: "Terkirim",
    accepted: "Diterima",
    rejected: "Ditolak",
    expired: "Expired",
};
const QT_STATUS_COLORS: Record<string, string> = {
    draft: COLORS.slateLight,
    waiting_approval: COLORS.orangeDark,
    approved: COLORS.navy,
    sent: COLORS.navyDark,
    accepted: COLORS.green,
    rejected: COLORS.red,
    expired: COLORS.slateLight,
};

function QuotationSummaryReportView({ color, filters, }: {
  color: string;
  filters: CrmReportFilters;
}) {
  const { data, isLoading, isError, error } = useQuotationSummaryReport(true, filters);
  if (isLoading || isError) {
    return (
      <div style={{ paddingTop: "1rem" }}>
        <ErrorOrLoading isLoading={isLoading} isError={isError} error={error} />
      </div>
    );
  }
  if (!data) return null;

  const statusChartRows = data.by_status.map(status => ({
    label: QT_STATUS_LABELS[status.status] ?? status.status,
    count: Number(status.count) || 0,
    total_value: Number(status.total_value) || 0,
    fill: QT_STATUS_COLORS[status.status] ?? COLORS.navy,
  }));
  const exportRows: ExportRow[] = data.by_status.map(status => ({
    Status: QT_STATUS_LABELS[status.status] ?? status.status,
    Jumlah: status.count,
    "Total Nilai": status.total_value,
  }));

  return (
    <div style={{ paddingTop: "1rem", display: "flex", flexDirection: "column", gap: "1.25rem" }}>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(3, minmax(0, 1fr))", gap: "0.75rem" }}>
        <StatBox label="Total Quotation" value={data.total_count} />
        <StatBox label="Approval Rate" value={String(data.approval_rate) + "%"} color={color} />
        <StatBox label="Rata-rata Nilai" value={formatCurrency(data.avg_value)} />
      </div>

      <ChartPanel
        title="Komposisi Quotation per Status"
        description="Proporsi quotation berdasarkan status. Arahkan kursor ke setiap segmen untuk melihat jumlah dan nilai quotation."
        height={300}
      >
        <div className="crm-donut-wrap">
          <ResponsiveContainer width="100%" height="100%">
            <PieChart>
              <Tooltip
                content={({ active, payload }) => {
                  const row = payload?.[0]?.payload as (typeof statusChartRows)[number] | undefined;
                  if (!active || !row) return null;
                  return (
                    <div style={{ ...CHART_TOOLTIP_STYLE, padding: "10px 12px" }}>
                      <div style={{ fontWeight: 800, marginBottom: 6 }}>{row.label}</div>
                      <div>Jumlah: {row.count.toLocaleString("id-ID")}</div>
                      <div>Total Nilai: {formatCurrency(row.total_value)}</div>
                    </div>
                  );
                }}
              />
              <Legend verticalAlign="bottom" height={34} wrapperStyle={{ fontSize: 10 }} />
              <Pie
                data={statusChartRows}
                dataKey="count"
                nameKey="label"
                cx="50%"
                cy="43%"
                innerRadius={62}
                outerRadius={96}
                paddingAngle={3}
                stroke="#FFFFFF"
                strokeWidth={3}
                isAnimationActive
                animationDuration={1150}
                animationEasing="ease-out"
              >
                {statusChartRows.map(row => <Cell key={row.label} fill={row.fill} />)}
              </Pie>
            </PieChart>
          </ResponsiveContainer>
          <div className="crm-donut-center" style={{ top: "39%" }}>
            <strong>{Number(data.total_count).toLocaleString("id-ID")}</strong>
            <span>Total Quotation</span>
          </div>
        </div>
      </ChartPanel>

      {data.monthly_trend.length > 0 && (
        <ChartPanel
          title="Tren Quotation Bulanan"
          description="Perubahan jumlah quotation dari bulan ke bulan; total nilai dapat dilihat saat titik grafik dipilih."
          height={270}
        >
          <ResponsiveContainer width="100%" height="100%">
            <AreaChart data={data.monthly_trend} margin={{ top: 12, right: 16, left: -18, bottom: 4 }}>
              <defs>
                <linearGradient id="crmQuotationTrendGradient" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="4%" stopColor={COLORS.orange} stopOpacity={0.38} />
                  <stop offset="96%" stopColor={COLORS.orange} stopOpacity={0.025} />
                </linearGradient>
              </defs>
              <CartesianGrid strokeDasharray="3 3" stroke="#EAF0F6" vertical={false} />
              <XAxis dataKey="month" tick={CHART_AXIS_TICK} tickLine={false} axisLine={{ stroke: COLORS.border }} />
              <YAxis allowDecimals={false} tick={CHART_AXIS_TICK} tickLine={false} axisLine={false} />
              <Tooltip
                contentStyle={CHART_TOOLTIP_STYLE}
                content={({ active, payload, label }) => {
                  const row = payload?.[0]?.payload as (typeof data.monthly_trend)[number] | undefined;
                  if (!active || !row) return null;
                  return (
                    <div style={{ ...CHART_TOOLTIP_STYLE, padding: "10px 12px" }}>
                      <div style={{ fontWeight: 800, marginBottom: 6 }}>{label}</div>
                      <div>Jumlah QT: {Number(row.count).toLocaleString("id-ID")}</div>
                      <div>Total Nilai: {formatCurrency(Number(row.total_value))}</div>
                    </div>
                  );
                }}
              />
              <Area type="monotone" dataKey="count" name="Jumlah Quotation" stroke={COLORS.orangeDark} strokeWidth={3} fill="url(#crmQuotationTrendGradient)" dot={{ r: 3.5, fill: COLORS.orangeDark, strokeWidth: 0 }} activeDot={{ r: 6 }} isAnimationActive animationDuration={1150} animationEasing="ease-out" />
            </AreaChart>
          </ResponsiveContainer>
        </ChartPanel>
      )}

      <ExportButtons reportName="Quotation Summary" filenameBase="quotation-summary" rows={exportRows} />
    </div>
  );
}


/* ============================================================
   EXPIRED QUOTATIONS
============================================================ */
function ExpiredQuotationsReportView({ filters, }: {
    filters: CrmReportFilters;
}) {
    const { data, isLoading, isError, error, } = useExpiredQuotationsReport(true, filters);
    if (isLoading || isError) {
        return (<div style={{
                paddingTop: "1rem",
            }}>
        <ErrorOrLoading isLoading={isLoading} isError={isError} error={error}/>
      </div>);
    }
    if (!data) {
        return null;
    }
    const exportRows: ExportRow[] = data.list.map((quotation) => ({
        "No QT": quotation.quotation_number,
        Customer: quotation.customer_name,
        "Berlaku s/d": formatDate(quotation.valid_until),
        Nilai: quotation.total_amount,
    }));
    return (<div style={{
            paddingTop: "1rem",
            display: "flex",
            flexDirection: "column",
            gap: "1rem",
        }}>
      <div style={{
            display: "grid",
            gridTemplateColumns: "repeat(3, minmax(0, 1fr))",
            gap: "0.75rem",
        }}>
        <StatBox label="Jumlah Expired" value={data.count} color={COLORS.red}/>

        <StatBox label="Rata-rata Nilai" value={formatCurrency(data.avg_value)}/>

        <StatBox label="Rata-rata Hari Sejak Expired" value={`${data.avg_days_since_expiry} hari`}/>
      </div>

      {data.list.length > 0 && (
        <ChartPanel
          title="Timeline Quotation Expired"
          description="Urutan quotation berdasarkan tanggal berakhir, untuk membantu menentukan prioritas tindak lanjut."
          height={Math.max(190, Math.min(data.list.length, 6) * 47 + 36)}
        >
          <div className="crm-expiry-timeline">
            {[...data.list]
              .sort((a, b) => Date.parse(a.valid_until) - Date.parse(b.valid_until))
              .slice(0, 6)
              .map(quotation => (
                <div className="crm-expiry-timeline-item" key={quotation.id}>
                  <span className="crm-expiry-timeline-dot" />
                  <div className="crm-expiry-timeline-main">
                    <strong>{quotation.quotation_number}</strong>
                    <span>{quotation.customer_name}</span>
                  </div>
                  <div className="crm-expiry-timeline-meta">
                    <strong>{formatCurrency(quotation.total_amount)}</strong>
                    <span>{formatDate(quotation.valid_until)}</span>
                  </div>
                </div>
              ))}
          </div>
        </ChartPanel>
      )}

      {data.list.length ===
            0 ? (<p style={{
                margin: 0,
                color: COLORS.slate,
                fontSize: "0.75rem",
            }}>
          Tidak ada quotation
          yang expired saat ini.
        </p>) : (<div style={{
                overflowX: "auto",
            }}>
          <table className="crm-report-table" style={reportTableStyle}>
            <thead>
              <tr>
                <ReportTh>
                  No QT
                </ReportTh>

                <ReportTh>
                  Customer
                </ReportTh>

                <ReportTh>
                  Berlaku s/d
                </ReportTh>

                <ReportTh align="right">
                  Nilai
                </ReportTh>
              </tr>
            </thead>

            <tbody>
              {data.list.map((quotation) => (<tr key={quotation.id}>
                    <ReportTd bold>
                      <Link to="/crm-sales/quotations" style={{
                        color: COLORS.orangeDark,
                        textDecoration: "none",
                    }}>
                        {quotation.quotation_number}
                      </Link>
                    </ReportTd>

                    <ReportTd>
                      {quotation.customer_name}
                    </ReportTd>

                    <ReportTd>
                      {formatDate(quotation.valid_until)}
                    </ReportTd>

                    <ReportTd align="right">
                      {formatCurrency(quotation.total_amount)}
                    </ReportTd>
                  </tr>))}
            </tbody>
          </table>
        </div>)}

      <ExportButtons reportName="Expired Quotations" filenameBase="expired-quotations" rows={exportRows}/>
    </div>);
}

/* ============================================================
   CONTRACT AGING
============================================================ */
function ContractAgingReportView({ filters, }: {
    filters: CrmReportFilters;
}) {
    const { data, isLoading, isError, error, } = useContractAgingReport(true, filters);
    if (isLoading || isError) {
        return (<div style={{
                paddingTop: "1rem",
            }}>
        <ErrorOrLoading isLoading={isLoading} isError={isError} error={error}/>
      </div>);
    }
    if (!data) {
        return null;
    }
    const exportRows: ExportRow[] = data.list.map((contract) => ({
        "No Contract": contract.contract_number,
        Customer: contract.customer_name,
        Berakhir: formatDate(contract.end_date),
        "Sisa Hari": contract.days_until_expiry ??
            "",
        MRR: contract.monthly_value,
    }));
    return (<div style={{
            paddingTop: "1rem",
            display: "flex",
            flexDirection: "column",
            gap: "1rem",
        }}>
      <div style={{
            display: "grid",
            gridTemplateColumns: "repeat(4, minmax(0, 1fr))",
            gap: "0.75rem",
        }}>
        <StatBox label="Expiring ≤30 Hari" value={data.expiring_30} color={COLORS.red}/>

        <StatBox label="Expiring ≤60 Hari" value={data.expiring_60} color={COLORS.orangeDark}/>

        <StatBox label="Expiring ≤90 Hari" value={data.expiring_90} color={COLORS.orange}/>

        <StatBox label="MRR Berisiko" value={formatCurrency(data.mrr_at_risk)} color={COLORS.red}/>
      </div>

      <ChartPanel
        title="Peta Risiko Kontrak"
        description="Jumlah kontrak yang memasuki periode akhir masa berlaku berdasarkan ambang 30, 60, dan 90 hari."
        height={220}
      >
        <div className="crm-risk-timeline">
          {[
            { label: "Maksimal 30 hari", value: Number(data.expiring_30) || 0, color: COLORS.red, note: "Prioritas tinggi" },
            { label: "Maksimal 60 hari", value: Number(data.expiring_60) || 0, color: COLORS.orangeDark, note: "Perlu tindak lanjut" },
            { label: "Maksimal 90 hari", value: Number(data.expiring_90) || 0, color: COLORS.orange, note: "Persiapan perpanjangan" },
          ].map(item => {
            const maxValue = Math.max(Number(data.expiring_30) || 0, Number(data.expiring_60) || 0, Number(data.expiring_90) || 0, 1);
            const width = item.value > 0 ? Math.max(3, item.value / maxValue * 100) : 0;
            return (
              <div className="crm-risk-row" key={item.label}>
                <div className="crm-risk-row-head">
                  <span><strong>{item.label}</strong> <span style={{ color: COLORS.slateLight }}>· {item.note}</span></span>
                  <strong>{item.value.toLocaleString("id-ID")} kontrak</strong>
                </div>
                <div className="crm-risk-track">
                  <span className="crm-risk-fill" style={{ width: `${width}%`, "--risk-color": item.color } as React.CSSProperties} />
                </div>
              </div>
            );
          })}
        </div>
      </ChartPanel>

      {data.list.length ===
            0 ? (<p style={{
                margin: 0,
                color: COLORS.slate,
                fontSize: "0.75rem",
            }}>
          Tidak ada contract yang
          akan expire dalam 90 hari
          ke depan.
        </p>) : (<div style={{
                overflowX: "auto",
            }}>
          <table className="crm-report-table" style={reportTableStyle}>
            <thead>
              <tr>
                <ReportTh>
                  No Contract
                </ReportTh>

                <ReportTh>
                  Customer
                </ReportTh>

                <ReportTh>
                  Berakhir
                </ReportTh>

                <ReportTh align="right">
                  Sisa Hari
                </ReportTh>

                <ReportTh align="right">
                  MRR
                </ReportTh>
              </tr>
            </thead>

            <tbody>
              {data.list.map((contract) => {
                const urgent = (contract.days_until_expiry ??
                    999) <=
                    30;
                return (<tr key={contract.id}>
                      <ReportTd bold>
                        <Link to="/crm-sales/contracts" style={{
                        color: COLORS.orangeDark,
                        textDecoration: "none",
                    }}>
                          {contract.contract_number}
                        </Link>
                      </ReportTd>

                      <ReportTd>
                        {contract.customer_name}
                      </ReportTd>

                      <ReportTd>
                        {formatDate(contract.end_date)}
                      </ReportTd>

                      <ReportTd align="right">
                        <span style={{
                        display: "inline-flex",
                        alignItems: "center",
                        gap: "0.25rem",
                        color: urgent
                            ? COLORS.red
                            : COLORS.orangeDark,
                        fontWeight: 700,
                    }}>
                          {urgent && (<AlertTriangle size={12}/>)}

                          {contract.days_until_expiry ??
                        "—"}{" "}
                          hari
                        </span>
                      </ReportTd>

                      <ReportTd align="right">
                        {formatCurrency(contract.monthly_value)}
                      </ReportTd>
                    </tr>);
            })}
            </tbody>
          </table>
        </div>)}

      <ExportButtons reportName="Contract Aging" filenameBase="contract-aging" rows={exportRows}/>
    </div>);
}

/* ============================================================
   CUSTOMER REVENUE
============================================================ */
const CUST_STATUS_LABELS: Record<string, string> = {
    prospect: "Prospect",
    active: "Aktif",
    inactive: "Tidak Aktif",
    churned: "Churned",
};
const CUST_STATUS_COLORS: Record<string, string> = {
    prospect: COLORS.navy,
    active: COLORS.green,
    inactive: COLORS.slateLight,
    churned: COLORS.red,
};

function CustomerRevenueReportView({ filters, }: {
  filters: CrmReportFilters;
}) {
  const { data, isLoading, isError, error } = useCustomerRevenueReport(true, filters);
  if (isLoading || isError) {
    return (
      <div style={{ paddingTop: "1rem" }}>
        <ErrorOrLoading isLoading={isLoading} isError={isError} error={error} />
      </div>
    );
  }
  if (!data) return null;

  const statusChartRows = data.by_status.map(status => ({
    label: CUST_STATUS_LABELS[status.status] ?? status.status,
    count: Number(status.count) || 0,
    fill: CUST_STATUS_COLORS[status.status] ?? COLORS.navy,
  }));
  const exportRows: ExportRow[] = data.top_customers.map(customer => ({
    Customer: customer.customer_name,
    Status: CUST_STATUS_LABELS[customer.status ?? ""] ?? customer.status ?? "—",
    "Kontrak Aktif": customer.contract_count,
    MRR: customer.mrr,
  }));
  const customerRevenueEntries: LeaderboardVisualEntry[] = [...data.top_customers]
    .sort((a, b) => Number(b.mrr ?? 0) - Number(a.mrr ?? 0))
    .slice(0, 8)
    .map((customer, index) => ({
      id: String(customer.customer_id ?? index),
      name: customer.customer_name,
      value: Number(customer.mrr) || 0,
      valueLabel: formatCompactCurrency(Number(customer.mrr) || 0),
      metaLabel: `${customer.contract_count} kontrak aktif`,
    }));

  return (
    <div style={{ paddingTop: "1rem", display: "flex", flexDirection: "column", gap: "1.25rem" }}>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(3, minmax(0, 1fr))", gap: "0.75rem" }}>
        <StatBox label="MRR Aktif" value={formatCurrency(data.total_mrr)} color={COLORS.orangeDark} />
        <StatBox label="ARR Aktif" value={formatCurrency(data.total_arr)} color={COLORS.orangeDark} />
        <StatBox label="Customer Berkontrak Aktif" value={data.customers_with_active_contract} />
      </div>

      <ChartPanel
        title="Komposisi Customer per Status"
        description="Proporsi customer berdasarkan status hubungan dan kontrak."
        height={300}
      >
        <div className="crm-donut-wrap">
          <ResponsiveContainer width="100%" height="100%">
            <PieChart>
              <Tooltip contentStyle={CHART_TOOLTIP_STYLE} formatter={(value) => [Number(value).toLocaleString("id-ID"), "Customer"]} />
              <Legend verticalAlign="bottom" height={34} wrapperStyle={{ fontSize: 10 }} />
              <Pie
                data={statusChartRows}
                dataKey="count"
                nameKey="label"
                cx="50%"
                cy="43%"
                innerRadius={62}
                outerRadius={96}
                paddingAngle={3}
                stroke="#FFFFFF"
                strokeWidth={3}
                isAnimationActive
                animationDuration={1150}
                animationEasing="ease-out"
              >
                {statusChartRows.map(row => <Cell key={row.label} fill={row.fill} />)}
              </Pie>
            </PieChart>
          </ResponsiveContainer>
          <div className="crm-donut-center" style={{ top: "39%" }}>
            <strong>{formatCompactCurrency(Number(data.total_mrr) || 0)}</strong>
            <span>MRR Aktif</span>
          </div>
        </div>
      </ChartPanel>

      {customerRevenueEntries.length > 0 && (
        <LeaderboardPanel
          title="Top Customer berdasarkan MRR"
          description="Peringkat customer dengan nilai Monthly Recurring Revenue tertinggi."
          entries={customerRevenueEntries}
          color={COLORS.orange}
        />
      )}

      {data.top_customers.length >
            0 && (<div>
          <SectionTitle>
            Top Customer (by MRR)
          </SectionTitle>

          <div style={{
                overflowX: "auto",
            }}>
            <table className="crm-report-table" style={reportTableStyle}>
              <thead>
                <tr>
                  <ReportTh>
                    Customer
                  </ReportTh>

                  <ReportTh>
                    Status
                  </ReportTh>

                  <ReportTh align="right">
                    Kontrak Aktif
                  </ReportTh>

                  <ReportTh align="right">
                    MRR
                  </ReportTh>
                </tr>
              </thead>

              <tbody>
                {data.top_customers.map((customer) => (<tr key={customer.customer_id}>
                      <ReportTd bold>
                        <Link to="/crm-sales/customers" style={{
                        color: COLORS.orangeDark,
                        textDecoration: "none",
                    }}>
                          {customer.customer_name}
                        </Link>
                      </ReportTd>

                      <ReportTd>
                        <span style={{
                        color: CUST_STATUS_COLORS[customer.status ??
                            ""] ??
                            COLORS.slate,
                        fontSize: "0.68rem",
                        fontWeight: 700,
                    }}>
                          {CUST_STATUS_LABELS[customer.status ??
                    ""] ??
                    customer.status ??
                    "—"}
                        </span>
                      </ReportTd>

                      <ReportTd align="right">
                        {customer.contract_count}
                      </ReportTd>

                      <ReportTd align="right" bold color={COLORS.orangeDark}>
                        {formatCurrency(customer.mrr)}
                      </ReportTd>
                    </tr>))}
              </tbody>
            </table>
          </div>
        </div>)}

      <ExportButtons reportName="Customer Revenue" filenameBase="customer-revenue" rows={exportRows} />
    </div>
  );
}


/* ============================================================
   SMALL VISUAL HELPERS
============================================================ */
function SectionTitle({ children, }: {
    children: React.ReactNode;
}) {
    return (<div className="crm-report-section-title">{children}</div>);
}

const reportTableStyle = {
    width: "100%",
    borderCollapse: "separate",
    borderSpacing: 0,
    tableLayout: "auto",
} as const;

function ReportTh({ children, align = "left", }: {
    children: React.ReactNode;
    align?: "left" | "right";
}) {
    return (<th style={{
            padding: "0.75rem 0.8rem",
            borderBottom: `1px solid ${COLORS.border}`,
            color: COLORS.slate,
            fontSize: "0.66rem",
            fontWeight: 800,
            textAlign: align,
            textTransform: "uppercase",
            letterSpacing: ".04em",
            whiteSpace: "nowrap",
        }}>
      {children}
    </th>);
}

function ReportTd({ children, align = "left", bold = false, color, }: {
    children: React.ReactNode;
    align?: "left" | "right";
    bold?: boolean;
    color?: string;
}) {
    return (<td style={{
            padding: "0.78rem 0.8rem",
            borderBottom: `1px solid ${COLORS.border}`,
            color: color ?? COLORS.navy,
            fontSize: "0.76rem",
            fontWeight: bold ? 750 : 450,
            textAlign: align,
            verticalAlign: "middle",
            whiteSpace: "nowrap",
        }}>
      {children}
    </td>);
}